/**
 * Which commit is actually live. Injected at build time via VITE_COMMIT_SHA
 * (see deploy-webend.yml); locally it reads 'dev' so nobody mistakes a dev
 * server for a release.
 */
export const BUILD_SHA: string = import.meta.env.VITE_COMMIT_SHA || 'dev'

const REPO_URL = 'https://github.com/SimpleVoiceChatWeb/webend'

export const COMMIT_URL: string =
  BUILD_SHA === 'dev' ? REPO_URL : `${REPO_URL}/commit/${BUILD_SHA}`
